INSERT OR IGNORE INTO lessons (id,course_id,slug,title,description,level,position,version,status) VALUES ('a1-u03-l01','course-a1-foundations','my-family','My Family','Name close family members and describe simple family relationships.','A1',11,1,'published');
INSERT OR IGNORE INTO questions (id,lesson_id,type,prompt,options_json,answer_key,explanation,position) VALUES
('a1-u03-l01-q01','a1-u03-l01','multiple_choice','Your mother''s daughter is your ___.','[{"id":"a","text":"sister"},{"id":"b","text":"uncle"},{"id":"c","text":"grandfather"}]','a','Your mother''s daughter can be your sister.',1),
('a1-u03-l01-q02','a1-u03-l01','multiple_choice','Complete: This is ___ father.','[{"id":"a","text":"I"},{"id":"b","text":"my"},{"id":"c","text":"me"}]','b','Use the possessive adjective my before a family noun.',2),
('a1-u03-l01-q03','a1-u03-l01','multiple_choice','Choose the correct sentence.','[{"id":"a","text":"He is my brother."},{"id":"b","text":"He are my brother."},{"id":"c","text":"He my brother is."}]','a','Use is with he.',3),
('a1-u03-l01-q04','a1-u03-l01','multiple_choice','Your mother''s mother is your ___.','[{"id":"a","text":"aunt"},{"id":"b","text":"grandmother"},{"id":"c","text":"cousin"}]','b','Your mother''s mother is your grandmother.',4);
INSERT OR IGNORE INTO lesson_versions (id,lesson_id,version,title,description,level,position,status,published_at) VALUES ('a1-u03-l01:v1','a1-u03-l01',1,'My Family','Name close family members and describe simple family relationships.','A1',11,'draft',NULL);
