INSERT OR IGNORE INTO lessons (id,course_id,slug,title,description,level,position,version,status) VALUES ('a1-u03-l02','course-a1-foundations','how-old-are-they','How Old Are They?','Ask and answer about the ages of family members using numbers to one hundred.','A1',12,1,'published');
INSERT OR IGNORE INTO questions (id,lesson_id,type,prompt,options_json,answer_key,explanation,position) VALUES
('a1-u03-l02-q01','a1-u03-l02','multiple_choice','Complete: How old ___ your sister?','[{"id":"a","text":"am"},{"id":"b","text":"is"},{"id":"c","text":"are"}]','b','Use is with one person: your sister.',1),
('a1-u03-l02-q02','a1-u03-l02','multiple_choice','Choose the correct answer: “How old is your father?”','[{"id":"a","text":"He is forty."},{"id":"b","text":"He forty is."},{"id":"c","text":"He are forty."}]','a','Use He is + age.',2),
('a1-u03-l02-q03','a1-u03-l02','multiple_choice','Which number is thirty?','[{"id":"a","text":"13"},{"id":"b","text":"30"},{"id":"c","text":"3"}]','b','Thirty is the number 30.',3),
('a1-u03-l02-q04','a1-u03-l02','multiple_choice','Complete: My grandparents ___ seventy.','[{"id":"a","text":"is"},{"id":"b","text":"am"},{"id":"c","text":"are"}]','c','Use are with a plural subject.',4);
