('a1-u03-l03-q02','a1-u03-l03','multiple_choice','Complete: She ___ got brown eyes.','[{"id":"a","text":"have"},{"id":"b","text":"has"},{"id":"c","text":"is"}]','b','Use has got with she.',2),
