INSERT OR IGNORE INTO lessons (id,course_id,slug,title,description,level,position,version,status) VALUES ('a1-u03-l04','course-a1-foundations','friends-and-likes','Friends and Likes','Talk about simple likes and dislikes and ask another person about preferences.','A1',14,1,'published');
INSERT OR IGNORE INTO questions (id,lesson_id,type,prompt,options_json,answer_key,explanation,position) VALUES
('a1-u03-l04-q01','a1-u03-l04','multiple_choice','Complete: I ___ music.','[{"id":"a","text":"likes"},{"id":"b","text":"like"},{"id":"c","text":"liking"}]','b','Use the base form like with I.',1),
('a1-u03-l04-q02','a1-u03-l04','multiple_choice','Choose the correct sentence.','[{"id":"a","text":"She like books."},{"id":"b","text":"She likes books."},{"id":"c","text":"She liking books."}]','b','Add -s to the present simple verb with she.',2),
('a1-u03-l04-q03','a1-u03-l04','multiple_choice','Choose a question about preferences.','[{"id":"a","text":"Do you like football?"},{"id":"b","text":"Are you like football?"},{"id":"c","text":"Does you like football?"}]','a','Use Do you + base verb for a question.',3),
('a1-u03-l04-q04','a1-u03-l04','multiple_choice','Choose the natural short answer: “Do you like tea?”','[{"id":"a","text":"Yes, I do."},{"id":"b","text":"Yes, I am."},{"id":"c","text":"Yes, I like do."}]','a','Use do in the short answer to a Do-question.',4);
