INSERT OR IGNORE INTO lessons (id,course_id,slug,title,description,level,position,version,status) VALUES ('a1-u03-l05','course-a1-foundations','whose-is-it','Whose Is It?','Ask who owns a familiar object and identify the owner using possessive ''s.','A1',15,1,'published');
