('a1-u03-l05-q02','a1-u03-l05','multiple_choice','Complete: ___ book is this?','[{"id":"a","text":"Who''s"},{"id":"b","text":"Whose"},{"id":"c","text":"Who"}]','b','Whose asks who owns something.',2),
('a1-u03-l05-q03','a1-u03-l05','multiple_choice','Choose the correct answer: “Whose bag is this?”','[{"id":"a","text":"It''s Ali''s bag."},{"id":"b","text":"It''s Ali bag."},{"id":"c","text":"It''s bag Ali."}]','a','Use the owner''s name + ''s + object.',3),
('a1-u03-l05-q04','a1-u03-l05','multiple_choice','This is my parents'' car. Who owns the car?','[{"id":"a","text":"my teacher"},{"id":"b","text":"my parents"},{"id":"c","text":"my friend"}]','b','Parents'' shows possession by more than one parent.',4);
